from starlette.responses import JSONResponse, Response
import json

def test_json_response_with_bytes():
    data = {"foo": "bar"}
    content = json.dumps(data).encode("utf-8")
    response = JSONResponse(content)
    assert response.body == content
    assert response.headers["content-type"] == "application/json"

def test_json_response_with_dict():
    data = {"foo": "bar"}
    response = JSONResponse(data)
    assert response.body == json.dumps(data).encode("utf-8")
    assert response.headers["content-type"] == "application/json"

if __name__ == "__main__":
    try:
        test_json_response_with_bytes()
        print("test_json_response_with_bytes passed")
    except Exception as e:
        print(f"test_json_response_with_bytes failed: {e}")

    try:
        test_json_response_with_dict()
        print("test_json_response_with_dict passed")
    except Exception as e:
        print(f"test_json_response_with_dict failed: {e}")

